onRecordCreateRequest((e)=>{require(__hooks+'/lib/domain.js').prepareRequest(e,true);return e.next();},'professionals','services','bookings','schedule_blocks','visits');
onRecordUpdateRequest((e)=>{require(__hooks+'/lib/domain.js').prepareRequest(e,false);return e.next();},'users','businesses','professionals','services','bookings','schedule_blocks');
onRecordCreate((e)=>{require(__hooks+'/lib/domain.js').aroundSave(e,true);},'businesses','professionals','services','bookings','schedule_blocks');
onRecordUpdate((e)=>{require(__hooks+'/lib/domain.js').aroundSave(e,false);},'businesses','professionals','services','bookings','schedule_blocks');
onRecordDeleteRequest((e)=>{e.record.set('_ap_actor',require(__hooks+'/lib/domain.js').actor(e));return e.next();},'schedule_blocks');
onRecordDelete((e)=>{const h=require(__hooks+'/lib/domain.js');e.app.runInTransaction(tx=>{e.app=tx;const before=h.snapshot(e.record),b=e.record.getString('business');e.next();h.audit(tx,b,'schedule_blocks',e.record.id,'deleted',e.record.getString('_ap_actor')||'system',before,{});h.bump(tx,b);});},'schedule_blocks');
onRecordCreateRequest((e)=>{throw new ForbiddenError('Registro exclusivo do servidor.');},'audit_log','access_log','demo_sessions','policy_acceptances');
onRecordUpdateRequest((e)=>{throw new ForbiddenError('Registro exclusivo do servidor.');},'audit_log','access_log','demo_sessions','policy_acceptances');
onRecordDeleteRequest((e)=>{throw new ForbiddenError('Registro exclusivo do servidor.');},'audit_log','access_log','demo_sessions','policy_acceptances');
onRecordAuthRequest((e)=>{const h=require(__hooks+'/lib/domain.js');if(e.authMethod==='password'&&e.record&&e.record.collection().name==='users'){const log=new Record(e.app.findCollectionByNameOrId('access_log'));log.load({business:e.record.getString('business'),user:e.record.id,accessed_at:h.now()});e.app.save(log);}return e.next();},'users');
routerUse(new Middleware((e)=>{const allowed=$os.getenv('FRONTEND_ORIGIN')||'http://127.0.0.1:8090',origin=e.request.header.get('Origin');if(origin&&origin!==allowed)throw new ForbiddenError('Origem não permitida.');e.response.header().set('Referrer-Policy','no-referrer');if(e.request.url.path.indexOf('/api/')===0)e.response.header().set('Cache-Control','no-store');return e.next();},-1042));
cronAdd('ap_expired_demo','0 * * * *',()=>{const h=require(__hooks+'/lib/domain.js');for(const r of h.list($app,'demo_sessions','expires_at < {:now}',{now:h.now()}))$app.delete(r);const maxDays=Number($os.getenv('VISIT_RETENTION_DAYS')||30);const before=new Date(Date.now()-maxDays*86400000).toISOString();$app.db().newQuery('DELETE FROM visits WHERE visited_at < {:before}').bind({before}).execute();});
